export function reactionFor(person, targetParty) {
  const own = person.party;
  const turn = person.dialogueTurn || 0;
  person.dialogueTurn = turn + 1;
  
  if (person.loyal && turn % 3 === 0) {
    const lines = [
      `Voetsek! My family has voted ${own} for generations — you won't turn me with empty promises!`,
      `Nee dankie, ek staan vas by ${own}! Julle ander partye kom net vir stemme en verdwyn!`,
      `You’re not getting my vote away from ${own}! What have you ever done for our block?`,
      `I’m ${own} all the way! Julle bly vir ons belowe maar ${own} is my party!`
    ];
    return lines[(person.voice + Math.floor(turn / 3)) % lines.length];
  }
  
  const lines = criticism[targetParty] || [
    'Julle bly vir ons belowe, maar niks gebeur nie! Not getting my vote today!',
    'Kak man, fix the potholes and sewage in our street first before asking for votes!',
    'Voetsek with your election posters! Where were you during the last 5 years?',
    'Eers water, ligte, jobs en veiligheid. Dan praat ons oor stemme!',
    'Show me working streetlights and medicine in our local clinic, not empty party slogans!'
  ];
  return lines[(person.voice + turn) % lines.length];
}

export function cheerFor(party) {
  const list = allyCheers[party] || allyCheers.default;
  return list[Math.floor(Math.random() * list.length)];
}
